  personalizedResult: ["YOUR ESTIMATE", "你的估算結果", "DEIN SCHÄTZWERT", "あなたの目安", "VOTRE ESTIMATION", "TU ESTIMACIÓN"],
  targetBounds: ["Tracker goals must be between 40 and 500 g. Review this estimate before saving.", "飲食紀錄的每日目標須為 40–500 克。儲存前請確認估算結果。", "Tagesziele im Tagebuch müssen zwischen 40 und 500 g liegen. Prüfe diesen Schätzwert vor dem Speichern.", "記録の目標は40〜500gで設定してください。保存前にこの目安を確認してください。", "Les objectifs du suivi doivent être compris entre 40 et 500 g. Vérifiez cette estimation avant de l’enregistrer.", "Los objetivos del registro deben estar entre 40 y 500 g. Revisa esta estimación antes de guardarla."],
  addedToLog: ["Added to today’s log.", "已新增至今天的紀錄。", "Zum heutigen Tagebuch hinzugefügt.", "今日の記録に追加しました。", "Ajouté au journal du jour.", "Añadido al registro de hoy."],
