export const MESSAGES = Object.fromEntries(
  LANGUAGES.map(({ id }, index) => [
    id,
    Object.fromEntries(Object.entries(rows).map(([key, values]) => [key, values[index]])),
  ]),
);

export function translate(lang, key, vars = {}) {
  const localized = MESSAGES[lang]?.[key];
  const english = MESSAGES.en[key];
  const message = typeof localized === "string" ? localized : typeof english === "string" ? english : String(key);
  return message.replace(/\{([^{}]+)\}/g, (placeholder, name) =>
    vars && Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : placeholder,
  );
}
